  s.image_attribution = 'Quentin Groom (CC0) · GBIF',
  s.rarity_score = 3,
  s.rarity_basis = NULL
WHERE p.slug = 'cabezo-gordo' AND s.scientific_name = 'Periploca angustifolia';

