  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Charadrius_alexandrinus_-_Kentish_Plover_03.jpg?width=1280',
  s.image_attribution = 'Zeynel Cebeci (CC BY-SA 4.0) · Wikimedia Commons',
