  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Ephedra_fragilis_3.JPG?width=1280',
  s.image_attribution = 'User:falconaumanni (CC BY-SA 4.0) · Wikimedia Commons',
