  s.image_attribution = 'Retama (CC BY-SA 3.0) · Wikimedia Commons',
  s.rarity_score = 2,
  s.rarity_basis = NULL
WHERE p.slug = 'carrascoy-y-el-valle' AND s.scientific_name = 'Eruca vesicaria';

