UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Lechuguilla',
  s.primary_habitat = 'Vive en herbazales y bordes de caminos, hasta 2100 m',
  s.description = 'Hierba anual, de 30-60 cm, con tallos glabros abajo. Hojas pinnatifidas, con aurículas agudas, con espínulas en el margen. Capítulos en grupos terminales, con involucro de 1-1,5 cm, con frecuencia abultado abajo y cóncavo, brácteas alargadas y separadas arriba, con pelos glandulíferos dispersos. Flores con lígulas amarillas. Aquenios de 2,5- 3,5 mm, comprimidos, con costillas longitudinales y tubérculos espinulosos; vilano al menos tres veces más largo que el aquenio.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
