  s.image_attribution = 'Denis Barthel (CC BY-SA 3.0 de) · Wikimedia Commons',
  s.rarity_score = 2,
  s.rarity_basis = NULL
WHERE p.slug = 'salinas-arenales-san-pedro-pinatar' AND s.scientific_name = 'Ajuga iva';

UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Ajestrín',
  s.primary_habitat = 'Vive en praderas, lugares incultos y dunas, hasta 2350 m',
  s.description = 'Hierba perenne, con bulbo de 1-2,5 cm, ovoide o globoso, con algunos bulbillos, y con tallo de 20-70 cm, de sección circular, macizo; inflorescencia esférica, densa, de 1,3-5,3 cm de diámetro, con una espata de dos segmentos ovados, más cortos que las flores; estas con pedicelos hasta de 2,1 cm, con tépalos de 3,5-6 mm, de color rosado o púrpura; estambres seis, los internos con filamentos tricuspidados; cápsula de 3-4,5 mm.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
  s.identification_tips = '',
  s.seasonality = 'Mayo a agosto',
