UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Magarza',
  s.primary_habitat = 'Vive en lugares alterados, como bordes de caminos o de cultivos, formando herbazales más o menos densos, hasta 1600 m',
  s.description = 'Hierba hasta de 50 cm, con hojas divididas pinnatisectas con segmentos lineares. Capítulos que nacen en escapos, de 2-4 cm de diámetro, con varias filas de brácteas lanceoladas u ovadas, agudas con margen escarioso, con lígulas blancas y flores flosculadas del receptáculo amarillas. Receptáculo con escamas. Aquenios de 2-4 mm, comprimidos lateralmente, los de la periferia alados, los centrales sin alas, sin vilano.',
