UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Agramen',
  s.primary_habitat = 'Herbazales húmedos en lugares algo nitrificados, hasta 1700 m',
  s.description = 'Hierba perenne rizomatosa, con estolones hasta de 1,5 m, rastreros, ramificados, enraizantes en los nudos. Tallos fértiles aéreos de 10-40 cm, glabros. Hojas dísticas, vaina de la hoja algo ciliada, lígula de pelos muy cortos; limbo de 1,5-12 x 0,2-0,5 cm, ± patente, glabro o hirsuto. Inflorescencia apical con tres a seis espigas digitadas de 2-6 cm cada una; formadas por espiguillas comprimidas de 2-2,5 mm, dispuestas en dos filas en la parte inferior del raquis. Glumas desiguales, la superior más larga, de 1,8-2,3 mm; glumillas de 2-2,5 mm. Fruto en cariópside, de 0,8-1,5 mm, oblongo, de color pardo oscuro.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
  s.identification_tips = '',
  s.seasonality = 'Todo el año',
  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Poaceae_spp_Sturm24.jpg?width=1280',
  s.image_attribution = 'Johann Georg Sturm (Painter: Jacob Sturm) (Public domain) · Wikimedia Commons',
  s.rarity_score = 2,
  s.rarity_basis = NULL
WHERE p.slug = 'salinas-arenales-san-pedro-pinatar' AND s.scientific_name = 'Cynodon dactylon';

UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Avallico',
  s.primary_habitat = 'Vive en pastizales secos, bordes de camino y sotobosques',
  s.description = 'Hierba perenne, hasta de 1,5 m, con tallos erectos. Hojas con lígulas hasta de 12 mm, y limbo hasta de 30 cm, con un nervio central. Inflorescencia en panícula de 2-30 cm, ovoide, densa, a veces abierta, con pedúnculo largo. Espiguillas de 4-6 mm, con glumas hasta de 5 mm, ciliadas, y lemas muy parecidas. Pálea con quillas ciliadas y con una pequeña arista.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
  s.identification_tips = '',
  s.seasonality = NULL,
