  s.seasonality = 'Primavera',
  s.image_url = 'https://observation.org/photos/144643107.jpg',
  s.image_attribution = 'Ans Gorter (CC BY-NC-ND 4.0) · observation.org / GBIF',
  s.rarity_score = 1,
