UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Lechuguino',
  s.primary_habitat = 'Vive en herbazales secos, eriales y suelos removidos, entre 100- 1100 m',
  s.description = 'Hierba perenne, de 15-60 cm, con raíz casi leñosa y tallos ramificados. Hojas dentadas o pinnatífidas, alternas, las superiores sentadas. Capítulos de 1 cm de diámetro, solitarios con largo pedúnculo algo engordado bajo el capítulo, este con brácteas agudas, más anchas las de abajo. Flores liguladas amarillas. Aquenios de 3 mm, los externos tuberculados, los internos lisos, con vilano de 8 mm.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
