UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Ortiga',
  s.primary_habitat = 'Vive en cultivos y lugares nitrificados, hasta 1500 m',
  s.description = 'Hierba anual, de 20-80 cm, erguida, con pelos urticantes poco abundantes. Hojas de 2-5 x 1-3 cm, ovadas o elípticas, agudas, dentadas. Inflorescencia en racimos axilares, espiciformes, hasta de 2,5 cm, con flores minúsculas masculinas con cuatro pétalos y cuatro estambres, y las femeninas con ovario ovoide y estigma capitado. Fruto en aquenio de 1 mm, ovoide, de color marrón.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
  s.identification_tips = '',
  s.seasonality = 'Octubre a junio',
  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/(MHNT)_Urtica_urens_-_leaves.jpg?width=1280',
  s.image_attribution = 'Didier Descouens (CC BY-SA 4.0) · Wikimedia Commons',
  s.rarity_score = 2,
  s.rarity_basis = NULL
WHERE p.slug = 'salinas-arenales-san-pedro-pinatar' AND s.scientific_name = 'Urtica urens';

