UPDATE species s JOIN parks p ON p.id = s.park_id SET
  s.common_name = 'Polluela pintoja',
  s.primary_habitat = NULL,
  s.description = 'La polluela pintoja es un ave de modesto tamaño, si bien algo mayor que el resto de sus congéneres, y su plumaje, aunque también críptico, se caracteriza por el abundante punteado blanquecino dibujado sobre el pecho grisáceo, diseño al que hace referencia el nombre vulgar de la especie. En la coloración de las regiones dorsales domina el pardo con estrías blancuzcas, en tanto que los flancos aparecen barrados de pardo, blanco y negro. Otro rasgo que la distingue de las otras polluelas es la tonalidad clara —blanco-amarillenta— que lucen las infracoberteras caudales. El pico es amarillento con la base rojiza. Las hembras, aunque similares a los machos, resultan en conjunto más apagadas y con un moteado más profuso, al igual que los jóvenes, si bien estos se diferencian por el color pardo del pico.',
  s.description_source = 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»',
  s.identification_tips = '',
  s.seasonality = 'Septiembre, octubre, febrero, marzo, abril',
  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Porzana_porzana_1_(Marek_Szczepanek).jpg?width=1280',
  s.image_attribution = 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons',
  s.rarity_score = 3,
  s.rarity_basis = NULL
WHERE p.slug = 'salinas-arenales-san-pedro-pinatar' AND s.scientific_name = 'Porzana porzana';

