  s.image_attribution = 'Me (Public domain) · Wikimedia Commons',
  s.rarity_score = 2,
  s.rarity_basis = NULL
WHERE p.slug = 'sierra-de-el-carche' AND s.scientific_name = 'Rapistrum rugosum';

