  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_culebrera_(Circaetus_gallicus).jpg?width=1280',
  s.image_attribution = 'Paco Gómez (CC BY-SA 4.0) · Wikimedia Commons',
