  s.image_url = 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceratonia_siliqua_Keciboynuzu_1370984_Nevit.jpg?width=1280',
  s.image_attribution = 'Nevit Dilmen (talk) (CC BY-SA 3.0) · Wikimedia Commons',
