  s.rarity_score = 2,
  s.rarity_basis = '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}'
WHERE p.slug = 'sotos-y-bosques-de-ribera-de-canaverosa' AND s.scientific_name = 'Galerida cristata';

